<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use App\Core\Database;use App\Services\AsaasHttpClient;use App\Services\AsaasSubcontaReconciliationService;
$o=getopt('',['proprietario-id:','admin-id:','dry-run','remote-read','create','confirm']);$db=Database::getConnection();if($db->query('SELECT current_database()')->fetchColumn()!=='alugfacil_dev')throw new RuntimeException('Banco nao permitido.');$svc=new AsaasSubcontaReconciliationService(new AsaasHttpClient(),$db);$candidates=$svc->candidatos();$pid=(int)($o['proprietario-id']??0);
if($pid<1){echo'CANDIDATOS='.count($candidates).PHP_EOL;foreach($candidates as$c)echo'proprietario_id='.(int)$c['proprietario_id'].' usuario_id='.(int)$c['usuario_id'].' documento='.AsaasSubcontaReconciliationService::mascara((string)$c['cpf_cnpj']).' email='.preg_replace('/(^.).*(@.*$)/','$1***$2',(string)$c['email_financeiro']).PHP_EOL;if(count($candidates)!==1){fwrite(STDERR,"Informe --proprietario-id explicitamente.\n");exit(2);}$pid=(int)$candidates[0]['proprietario_id'];}
$d=$svc->proprietario($pid);echo'SELECIONADO proprietario_id='.$pid.' usuario_id='.(int)$d['usuario_id'].' documento='.AsaasSubcontaReconciliationService::mascara((string)$d['cpf_cnpj']).' email='.preg_replace('/(^.).*(@.*$)/','$1***$2',(string)$d['email_financeiro']).PHP_EOL;if(!isset($o['remote-read'])){echo"DRY-RUN LOCAL: nenhuma chamada externa.\n";exit(0);}if(!isset($o['confirm'])){fwrite(STDERR,"Consulta remota exige --confirm e comprovacao de rotacao.\n");exit(2);}$out=$svc->reconciliar($pid,isset($o['create']),(int)($o['admin-id']??0));$row=$out['registro'];echo'RESULTADO='.$out['resultado'].PHP_EOL;if($row)echo'account='.AsaasSubcontaReconciliationService::mascara((string)$row['asaas_account_id']).' wallet='.AsaasSubcontaReconciliationService::mascara((string)$row['asaas_wallet_id']).' status='.$row['status_local'].PHP_EOL;
